 stale=g->data;stale["transform"]=QJsonArray{QJsonArray{1,2,3},0,0,1,0,0};stale["transformId"]=transformId(stale["transform"].toArray());raw=std::make_shared<const TextGeometry>(stale);check(selectScreenRangeChecked(raw,110,110,180,110,1).status==RangeStatus::InvalidGeometry,"nested_transform_value_rejected");
 stale=g->data;stale["document"]="bad-id";raw=std::make_shared<const TextGeometry>(stale);check(selectScreenRangeChecked(raw,110,110,180,110,1).status==RangeStatus::InvalidGeometry,"invalid_document_identity_rejected");
 stale=g->data;stale["words"]=QJsonArray{QJsonArray{-1,99999}};raw=std::make_shared<const TextGeometry>(stale);check(selectScreenRangeChecked(raw,110,110,180,110,1).status==RangeStatus::InvalidGeometry,"malformed_token_ranges_rejected");
 for(auto bad:{-1.0,1620.0,std::numeric_limits<double>::infinity(),std::numeric_limits<double>::quiet_NaN()})check(selectScreenRangeChecked(g,bad,110,180,110,1).status==RangeStatus::InvalidCoordinates,"bad_coordinates_rejected");check(selectScreenRangeChecked(g,110,2060,180,110,1).status==RangeStatus::InvalidCoordinates,"footer_outside_selection");
 check(selectScreenRangeChecked({},110,110,120,110,1).status==RangeStatus::Unavailable&&!selectScreenRange({},110,110,120,110,1),"missing_geometry_unavailable");check(selectScreenRangeChecked(geometry(""),110,110,120,110,1).status==RangeStatus::NoTextLayer,"empty_scanned_page_has_no_selection");check(selectScreenRangeChecked(geometry("..."),110,110,120,110,1).status==RangeStatus::NoTextLayer,"punctuation_only_page_has_no_tokens");
