 {auto a=point(many,1),b=point(many,longText.size()-2);auto full=selectScreenRangeChecked(many,a.first,a.second,b.first,b.second,100,true,true);check(full.selection&&full.selection->utf8()==longText.toUtf8()&&full.glyphCount==unsigned(many->data["chars"].toArray().size()),"vertical_block_includes_every_intermediate_glyph");auto punctuation=geometry("One paragraph.\nLast sentence!");a=point(punctuation,5);b=point(punctuation,20);full=selectScreenRangeChecked(punctuation,a.first,a.second,b.first,b.second,101,true,true);check(full.selection&&full.selection->utf8()==QByteArray("One paragraph.\nLast sentence!"),"full_paragraph_keeps_boundary_words_and_punctuation");}
 {auto trailing=geometry("One paragraph.\n");auto a=point(trailing,1),b=point(trailing,6);auto selected=selectScreenRangeChecked(trailing,a.first,a.second,b.first,b.second,102,true,true);check(selected.selection&&selected.selection->utf8()==QByteArray("One paragraph.\n")&&selected.utf16Count==15,"block_scope_preserves_trailing_source_linebreak");auto merged=mergeSelection(trailing,{},selected.selection,103);check(merged&&merged->data["text"]==selected.selection->data["text"]&&merged->id()==selected.selection->id(),"full_block_snapshot_survives_canonical_controller_merge");}
 QString tooLong;for(int i=0;i<60;++i){if(i)tooLong+='\n';tooLong+=QString(70,'a');}auto over=geometry(tooLong);auto limited=range(over,1,tooLong.size()-2);check(limited.status==RangeStatus::CapacityExceeded&&!limited.selection&&limited.glyphCount==4200&&std::string(rangeStatusText(limited.status))=="Select a smaller passage","glyph_capacity_has_explicit_reason_no_truncation");
