 {auto passages=geometry("alpha hidden beta omitted gamma");auto a=range(passages,1,3).selection,b=range(passages,14,16).selection,c=range(passages,27,29).selection;auto merged=mergeSelection(passages,a,b,100);check(merged&&merged->data["text"]=="alpha\n\nbeta"&&merged->data["quads"].toArray().size()==9&&selectionRanges(merged->data).size()==2,"separate_passages_exclude_hidden_gap_text_and_geometry");auto more=mergeSelection(passages,merged,c,101);check(more&&more->data["text"]=="alpha\n\nbeta\n\ngamma"&&selectionRanges(more->data).size()==3,"selection_append_retains_prior_ranges");auto duplicate=mergeSelection(passages,more,a,102);check(duplicate&&duplicate->data["text"]==more->data["text"]&&duplicate->data["quads"]==more->data["quads"],"duplicate_append_keeps_exact_union");auto spanning=range(passages,1,16).selection;auto unioned=mergeSelection(passages,merged,spanning,103);check(unioned&&selectionRanges(unioned->data).size()==1&&unioned->data["text"]=="alpha hidden beta","overlapping_ranges_merge_with_explicitly_selected_interior");auto edge=replaceSelectionEdge(passages,more,range(passages,14,21).selection,false,104);check(edge&&edge->data["text"]=="alpha\n\nbeta omitted"&&selectionRanges(edge->data).size()==2,"outer_handle_edit_keeps_other_selected_passages");auto bad=b->data;bad["text"]="invented";check(!mergeSelection(passages,a,std::make_shared<const SelectionSnapshot>(bad),105),"append_rejects_text_not_in_source");bad=b->data;bad["transformId"]=QString(64,'0');check(!mergeSelection(passages,a,std::make_shared<const SelectionSnapshot>(bad),105),"append_rejects_stale_view_binding");QJsonArray tooMany;for(int i=0;i<33;++i)tooMany.append(QJsonArray{i*2,i*2+1});check(!selectionFromRanges(geometry(QString(100,'a')),tooMany,106),"range_count_capacity_never_silently_truncates");}
